// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract ReentryAttacker {
    ReentrancyDAO public dao;
    uint256 public deposited;
    uint256 public received;
    uint256 public maxReentries;
    uint256 public count;

    constructor(ReentrancyDAO _dao) {
        dao = _dao;
    }

    function attack(uint256 _max) external payable {
        maxReentries = _max;
        deposited = msg.value;
        dao.deposit{value: msg.value}();
        dao.withdrawAll();
    }

    receive() external payable {
        received += msg.value;
        if (count < maxReentries) {
            count++;
            (bool ok, ) = address(dao).call(abi.encodeWithSignature("withdrawAll()"));
            ok;
        }
    }
}

contract HonestUser {
    ReentrancyDAO public dao;

    constructor(ReentrancyDAO _dao) {
        dao = _dao;
    }

    function deposit() external payable {
        dao.deposit{value: msg.value}();
    }
}

contract InvMutTest is Test {
    function _attack(uint256 dep, uint256 honestFund, uint256 reenter)
        internal
        returns (uint256 recv, uint256 dpst)
    {
        ReentrancyDAO dao = new ReentrancyDAO();
        HonestUser honest = new HonestUser(dao);
        vm.deal(address(honest), honestFund);
        honest.deposit{value: honestFund}();
        ReentryAttacker att = new ReentryAttacker(dao);
        vm.deal(address(att), dep);
        att.attack{value: dep}(reenter);
        return (att.received(), att.deposited());
    }

    function testFuzz_reentrancyNoProfit(uint96 dep, uint96 honestFund, uint8 reenter) public {
        uint256 d = bound(uint256(dep), 1, 1e24);
        uint256 h = bound(uint256(honestFund), 0, 1e24);
        uint256 r = bound(uint256(reenter), 0, 10);
        (uint256 recv, uint256 dpst) = _attack(d, h, r);
        assertLe(recv, dpst);
    }
}
